-- Store expertise/group icons and group colours in the database (TP-0098)
-- Adds nullable Icon to Expertise and Expertise_Groups, and nullable Color to
-- Expertise_Groups, then backfills the values previously hardcoded in
-- src/lib/managers/expertise-icons.ts.

ALTER TABLE `Expertise`        ADD COLUMN `Icon`  TEXT        NULL DEFAULT NULL;
ALTER TABLE `Expertise_Groups` ADD COLUMN `Icon`  TEXT        NULL DEFAULT NULL;
ALTER TABLE `Expertise_Groups` ADD COLUMN `Color` VARCHAR(7)  NULL DEFAULT NULL;

-- Backfill expertise icons (ids 1-9, matching the previous EXPERTISE_INFO map).
